-- V0026: Обновляем все шаблоны документов полными текстами по оригинальным PDF
-- Договор бытового подряда (contract)
UPDATE t_p24868917_kitchen_cost_calcula.doc_templates SET blocks = '[
  {"id":"hdr","type":"header","label":"Шапка","content":"ДОГОВОР\nбытового подряда на изготовление мебели  № {{номер_договора}}\nг. {{город}}                                                                                    {{дата_договора}}","enabled":true,"align":"center"},
  {"id":"intro","type":"paragraph","label":"Преамбула","content":"{{компания}}, в лице менеджера  {{менеджер}} действующего на основании доверенности № {{номер_доверенности}} от {{дата_доверенности}} именуемый в дальнейшем «Подрядчик» и гр.   {{имя_клиента}}\nименуемый (ая) в дальнейшем «Заказчик», действующий (ая) как физическое лицо, с одной стороны, отдельно именуемые – «Сторона», а совместно именуемые  - «Стороны», заключили настоящий Договор о нижеследующем:","enabled":true,"align":"justify"},
  {"id":"s1","type":"section","label":"1. ПРЕДМЕТ ДОГОВОРА","content":"1. ПРЕДМЕТ ДОГОВОРА","enabled":true,"align":"center"},
  {"id":"s1p1","type":"paragraph","label":"1.1","content":"1.1. Подрядчик обязуется выполнить работу по изготовлению мебели и передать результат работы Заказчику (мебель передаётся в разобранном виде), а Заказчик обязуется принять и оплатить результат работ.","enabled":true,"align":"justify"},
  {"id":"s1p2","type":"paragraph","label":"1.2","content":"1.2. Наименование, качественные характеристики, количество, дизайн мебели указываются в Техническом проекте, который является Приложением № 1 к настоящему Договору.","enabled":true,"align":"justify"},
  {"id":"s1p3","type":"paragraph","label":"1.3","content":"1.3. В случае необходимости выполнения Подрядчиком дополнительных работ, влекущих изменение объема, цены работ, включая изменение срока выполнения работ, стороны согласовывают данные изменения путем заключения дополнительного соглашения.","enabled":true,"align":"justify"},
  {"id":"s1p4","type":"paragraph","label":"1.4 — Срок","content":"1.4. Срок выполнения работ составляет {{срок_изготовления}} ({{срок_изготовления_прописью}}) рабочих дней с момента согласования Технического проекта и получения Подрядчиком предварительной оплаты, в размере, указанном в разделе 3 Договора. Подрядчик вправе досрочно выполнить работу без получения предварительного согласия Заказчика.\n\n1.4.1. В случае нарушения технологического процесса (поломка, остановка производственных линий, отсутствие энергоснабжения) по вине коммунальных и иных служб, нехватки сырья и (или) рабочей силы, если эти обстоятельства непосредственно повлияли на возможность надлежащего исполнения Сторонами своих обязательств по настоящему Договору, срок изготовления мебели переносится соразмерно времени, в течение которого действовали такие обстоятельства. В случае переноса сроков изготовления мебели по причине возникновения таких обстоятельств, Подрядчик уведомляет Заказчика о сроках переноса изготовления мебели в письменном виде по имеющимся средствам связи (социальные мессенджеры, электронная почта) с последующим заключением дополнительного соглашения об увеличении сроков по Договору.\n\n1.4.2. Если Заказчик не обеспечил возможности проезда Подрядчика к месту разгрузки мебели, Подрядчик не несет ответственности за сроки доставки и разгрузки мебели и оставляет за собой право выставить счет за компенсацию дополнительных затрат, понесенных в связи с доставкой мебели, который Заказчик обязуется оплатить в течение 3 (трёх) рабочих дней.","enabled":true,"align":"justify"},
  {"id":"s1p5","type":"paragraph","label":"1.5","content":"1.5. Работы, выполняемые Подрядчиком, предназначены удовлетворять бытовые или другие личные потребности Заказчика.","enabled":true,"align":"justify"},
  {"id":"s1p6","type":"paragraph","label":"1.6","content":"1.6. Заказчик проинформирован о том, что допускается отклонение оттенка цвета и текстуры покрытий мебели и (или) ее элементов, по сравнению с образцами, в пределах одного цветового тона, что не будет являться нарушением условий договора и основанием для предъявления соответствующих претензий Подрядчику.","enabled":true,"align":"justify"},
  {"id":"s1p7","type":"paragraph","label":"1.7","content":"1.7. Мебель изготавливается согласно индивидуальному заказу Заказчика (Технический проект). Подписанием данного договора Заказчик подтверждает, что им согласованы все характеристики мебели указанные в нём, не ограничиваясь: количество, размер, форма, габариты, материал, расцветка, комплектация, отделка, фурнитура, крепления и т.д. В связи с этим, на данный Договор не распространяются положения Закона РФ «О защите прав потребителей», в части возможности реализации потребителем права заменить товар или возвратить товар надлежащего качества.","enabled":true,"align":"justify"},
  {"id":"s2","type":"section","label":"2. ТЕХНИЧЕСКИЙ ПРОЕКТ","content":"2. РАЗРАБОТКА И СОГЛАСОВАНИЕ ТЕХНИЧЕСКОГО ПРОЕКТА","enabled":true,"align":"center"},
  {"id":"s2p1","type":"paragraph","label":"2.1","content":"2.1. Технический проект разрабатывается Подрядчиком в течение 10 (десяти) рабочих дней с момента получения Подрядчиком предварительной оплаты, в размере, указанном в разделе 3 Договора.","enabled":true,"align":"justify"},
  {"id":"s2p2","type":"paragraph","label":"2.2","content":"2.2. Заказчик в течение 5 (пяти) рабочих дней с момента перечисления предварительной оплаты обеспечивает доступ Подрядчика в помещение, в котором будет установлена мебель для проведения замеров помещения.","enabled":true,"align":"justify"},
  {"id":"s2p3","type":"paragraph","label":"2.3","content":"2.3. Заказчик не позднее 5 (пяти) рабочих дней со дня получения от Подрядчика Технического проекта согласовывает, путем проставления личной подписи и даты согласования, или направляет мотивированный отказ от согласования Технического проекта в редакции Подрядчика с предложением своих замечаний/ корректировок. В случае направления Заказчиком своих предложений/замечаний Подрядчик в течение 3 (трех) рабочих дней вносит изменения в Технический проект и направляет его на согласование Заказчику повторно.\nСтороны согласовали допустимость не более 2 (двух) кругов правок в представленный Подрядчиком Технический проект. Правки Технического проекта более 2-х раз будут оценены Подрядчиком как дополнительные работы, подлежащие оплате на основании счета Подрядчика из расчета 5 000 (пять тысяч) рублей за каждый повторный Технический проект с изменениями и дополнениями Заказчика.","enabled":true,"align":"justify"},
  {"id":"s2p4","type":"paragraph","label":"2.4","content":"2.4. Все изменения или дополнения после подписания Сторонами Технического проекта по инициативе Заказчика недопустимы, за исключением изменений и дополнений, которые Подрядчик признает существенными (изменение параметров помещения по обстоятельствам, не зависящим от Заказчика и т.п.).","enabled":true,"align":"justify"},
  {"id":"s2p5","type":"paragraph","label":"2.5","content":"2.5. Заказчик обязуется в течение 3 (трех) рабочих дней с момента наступления обстоятельств, в силу которых возникла необходимость внесения изменений или дополнений в Технический проект, направить Подрядчику письменное уведомление с указанием перечня таких изменений или дополнений, а также обосновать причины внесения изменений или дополнений в Технический проект.","enabled":true,"align":"justify"},
  {"id":"s2p6","type":"paragraph","label":"2.6","content":"2.6. Подрядчик в течение 5 (пяти) рабочих дней с момента получения уведомления о внесении изменений или дополнений в Технический проект сообщает Заказчику о возможности или невозможности таких изменений или дополнений. В случае, если изменения или дополнения Технического проекта повлекут увеличение стоимости, сроков изготовления и иных условий, стороны внесут соответствующие изменения в договор путем заключения дополнительного соглашения.","enabled":true,"align":"justify"},
  {"id":"s3","type":"section","label":"3. СТОИМОСТЬ И РАСЧЁТЫ","content":"3. СТОИМОСТЬ РАБОТ И ПОРЯДОК РАСЧЁТОВ","enabled":true,"align":"center"},
  {"id":"s3p1","type":"paragraph","label":"3.1 — Стоимость","content":"3.1. Общая стоимость работ, подлежащих выполнению по настоящему Договору складывается на основании Калькуляции (Приложение №2 к настоящему договору) и составляет   {{сумма}} ({{сумма_прописью}})\nрублей, НДС не облагается на основании ст. 346.11 НК РФ. В стоимость работ включается стоимость материалов Подрядчика, из которых производятся работы.","enabled":true,"align":"justify"},
  {"id":"s3p2_header","type":"paragraph","label":"3.2 — Порядок оплаты","content":"3.2. Оплата работ осуществляется в следующем порядке:","enabled":true,"align":"justify"},
  {"id":"s3p2_cash","type":"paragraph","label":"3.2 — Наличные/безнал","content":"3.2.1. Предварительная оплата производится при заключении Договора в размере {{аванс}} ({{аванс_прописью}}) рублей.\n\n3.2.2. Окончательный платёж за выполненные по Договору работы в размере    {{остаток}} ({{остаток_прописью}}) рублей, осуществляется в течение 3 (трёх) дней с момента получения Заказчиком уведомления о готовности мебели, но не позднее дня доставки мебели Заказчику, в случае если доставка осуществляется силами {{компания}} на основании отдельно заключённого договора.\n\n3.3. Оплата производится безналичным расчётом на счёт Подрядчика либо наличными денежными средствами в кассу Подрядчика.\n3.4. Обязательство Заказчика по безналичной оплате считается исполненным в момент зачисления денежных средств на счёт Подрядчика, указанный в реквизитах.","enabled":true,"align":"justify","condition":{"field":"payment_type","operator":"neq","value":"credit"}},
  {"id":"s3p2_credit","type":"paragraph","label":"3.2 — Рассрочка/кредит","content":"3.2.1. Предварительная оплата производится при заключении Договора в размере {{аванс_кредит}} ({{аванс_прописью}}) рублей, за счёт заёмных средств, при оформлении Заказчиком кредитного договора № {{номер_кредита}} от {{дата_кредита}}, заключённым между Заказчиком и Банком {{банк_кредита}} на приобретение мебели и выплачивается Банком за Заказчика на условиях и в порядке, определённых кредитным договором.\n\n3.2.2. Окончательный платёж за выполненные по Договору работы в размере {{остаток_кредит}} ({{остаток_прописью}}) рублей, осуществляется за счёт заёмных средств, при оформлении Заказчиком кредитного договора № {{номер_кредита}} от {{дата_кредита}}, заключённым между Заказчиком и Банком {{банк_кредита}} на приобретение мебели и выплачивается Банком за Заказчика на условиях и в порядке, определённых кредитным договором.\n\n3.3. Оплата производится безналичным расчётом на счёт Подрядчика либо наличными денежными средствами в кассу Подрядчика.\n3.4. Обязательство Заказчика по безналичной оплате считается исполненным в момент зачисления денежных средств на счёт Подрядчика, указанный в реквизитах.","enabled":true,"align":"justify","condition":{"field":"payment_type","operator":"eq","value":"credit"}},
  {"id":"s4","type":"section","label":"4. ПРАВА И ОБЯЗАННОСТИ","content":"4. ПРАВА И ОБЯЗАННОСТИ СТОРОН","enabled":true,"align":"center"},
  {"id":"s4p1","type":"paragraph","label":"4.1 — Обязанности подрядчика","content":"4.1. Подрядчик обязан:\n4.1.1. Выполнить работу по Договору согласно Техническому проекту и передать Заказчику мебель в установленный срок.\n4.1.2. Уведомить Заказчика о готовности мебели по электронной почте, путём обмена сообщениями (Telegram, WhatsUp, СМС и т.д.) на телефонный номер Сторон согласно реквизитам, указанным в Договоре.\n4.1.3. Устранить недостатки, выявленные Заказчиком по результатам приёмки работ.\n4.1.4. Предоставить Заказчику необходимую и достоверную информацию о предлагаемой работе, её видах и особенностях, о цене и форме оплаты, а также сообщить об иных относящихся к Договору и соответствующей работе сведениях. Подтверждением предоставления Заказчику указанной информации и его ознакомление с ней будет являться подписание Заказчиком настоящего Договора.\n4.1.5. Предупредить Заказчика о возможных неблагоприятных для него последствиях выполнения его указаний о способе исполнения работы, а также иных не зависящих от Подрядчика обстоятельствах, которые грозят годности или прочности результатов выполняемой работы либо создают невозможность её завершения в срок.","enabled":true,"align":"justify"},
  {"id":"s4p2","type":"paragraph","label":"4.2 — Обязанности заказчика","content":"4.2. Заказчик обязан:\n4.2.1. Согласовать и подписать Технический проект в срок, установленный Договором.\n4.2.2. Оплатить стоимость работ в соответствии с условиями настоящего Договора.\n4.2.3. Принять результат работ путём подписания Акта выполненных работ.\n4.2.4. Обеспечить сохранность помещения, в котором должна быть установлена мебель в том виде, в котором помещение было на момент проведения замеров Подрядчиком.\n4.2.5. Проводить ремонтно-отделочные работы в помещении, где будет размещена мебель, в строгом соответствии с Техническим проектом и только после получения письменного согласия Подрядчика на проведение таких работ.\n4.2.6. Предоставлять Подрядчику информацию необходимую для выполнения работ по Договору и отражения её в Техническом проекте, в том числе, но не ограничиваясь:\n- систему крепления мебели. При системе крепления мебели без врезки задней стенки ДВП между стеной и мебелью (например, при монтаже верхних шкафов будет зазор 10-20мм), что позволяет скрывать строительные дефекты (При системе крепления мебели с «утопленной» задней стенкой - зазор будет исключён, но для обеспечения такого крепления требуется наличие идеально ровных стен без строительных дефектов (впадин, бугров и т.д.));\n- места при установке мебели, в которых зазоры не приемлемы для Заказчика;\n- свес кухонной столешницы с лицевой стороны и у стены;\n- месторасположение и размеры техники (холодильник, вытяжка, варочная панель или газовая плита и т.д.), а также указать свои предпочтения по выбору техники для возможности получения у Подрядчика консультации по подбору рамки и (или) техники при эксплуатации техники и мебели;\n- особенности отделки и (или) ремонта помещения (неровные стены, полы разного уровня, навесной потолок, карнизы, наличие осветительных приборов, наличие труб, стояков, радиаторов и т.д.);\n- элементы декора, фотопечать, цветовые решения.","enabled":true,"align":"justify"},
  {"id":"s4p3","type":"paragraph","label":"4.3 — Права подрядчика","content":"4.3. Подрядчик вправе:\n4.3.1. Требовать подписания Заказчиком Акта выполненных работ в течение 5 (пяти) календарных дней с даты передачи мебели Заказчику.\n4.3.2. Требовать своевременной оплаты Работ в соответствии с п. 3.2 настоящего Договора.\n4.3.3. Запрашивать у Заказчика разъяснения и уточнения относительно порядка выполнения Работ.\n4.3.4. Привлекать третьих лиц для исполнения обязательств по настоящему Договору. Подрядчик несёт ответственность за действия/бездействие третьих лиц, выполняющих работу по Договору, как за свои собственные.\n4.3.5. Не приступать к Работе, а начатую Работу приостановить в случаях, когда нарушение Заказчиком своих обязанностей, установленных в п. 4.2 Договора препятствует исполнению Договора, а также при наличии обстоятельств, очевидно свидетельствующих о том, что исполнение указанных обязанностей не будет произведено в установленный срок.\n4.3.6. Самостоятельно определить количество специалистов, необходимых для выполнения работ, график работы, а также сроки в зависимости от сложности Изделия.\n4.3.7. Досрочно выполнить работы и требовать от Заказчика принять результат работы и произвести её оплату.\n4.3.8. В рекламных целях сделать фотоснимки изготовленной и установленной на месте мебели.","enabled":true,"align":"justify"},
  {"id":"s4p4","type":"paragraph","label":"4.4 — Права заказчика","content":"4.4. Заказчик вправе:\n4.4.1. Выбрать модель мебели, цвет, компоновку, дизайн, материалы, фурнитуру из которых будет выполнена работа.\n4.4.2. Отозвать согласие на обработку своих персональных данных Подрядчиком.","enabled":true,"align":"justify"},
  {"id":"s5","type":"section","label":"5. ГАРАНТИЯ","content":"5. ГАРАНТИЯ И КАЧЕСТВО ВЫПОЛНЕННЫХ РАБОТ","enabled":true,"align":"center"},
  {"id":"s5g","type":"paragraph","label":"5 — Гарантия","content":"5.1. Подтверждением качества мебели со стороны Подрядчика являются сертификаты соответствия, паспорта на товар, инструкции по эксплуатации и иная документация, удостоверяющие соответствие мебели характеристикам качества мебели на момент доставки в соответствии с условиями настоящего Договора.\nГарантийный срок на мебельную фурнитуру (петли, выдвижные механизмы, выдвижные корзины, подъёмные механизмы, сушки для посуды и т.п.) составляет 6 месяцев, гарантийный срок на мебель (корпус, фасады, столешницы) составляет 24 месяца, которые исчисляются с даты подписания Сторонами акта сдачи-приёмки выполненных Работ. Срок службы изделий – 5 лет.\nГарантийный срок эксплуатации Мебели и срок службы Мебели не распространяются на светильники, таймеры и другие встроенные бытовые приборы. Гарантийный срок таких приборов и срок службы указаны в паспорте на эти приборы.","enabled":true,"align":"justify"},
  {"id":"s6","type":"section","label":"6. ПРИЁМКА","content":"6. ПОРЯДОК ПРИЁМКИ ВЫПОЛНЕННЫХ РАБОТ","enabled":true,"align":"center"},
  {"id":"s6p1","type":"paragraph","label":"6.1–6.5","content":"6.1. По факту выполнения работ Подрядчик представляет Заказчику Акт выполненных работ в двух экземплярах по форме, согласованной в Приложении № 3 к Договору. При необоснованном отказе одной из сторон от подписания акта в нём делается отметка об этом и акт подписывается другой стороной в одностороннем порядке.\n6.2. Передача мебели производится по Акту выполненных работ, который составляется в момент передачи мебели.\n6.3. Приёмка изготовленной мебели производится: - в случае самовывоза Заказчиком по адресу склада Подрядчика;\n- в случае доставки мебели Подрядчиком в рамках заключённого между Заказчиком и Подрядчиком дополнительного договора доставки мебели по адресу Заказчика.\n6.4. При самовывозе Заказчиком мебели Подрядчик обеспечивает погрузку мебели на своём складе в транспортное средство Заказчика (перевозчика Заказчика), а Заказчик - их транспортировку и выгрузку.\n6.5. Заказчик обязан в течение 3 (трёх) календарных дней с даты получения уведомления от Подрядчика о готовности мебели к поставке, прибыть на склад Подрядчика для выборки мебели, в установленные в уведомлении дату и время.","enabled":true,"align":"justify"},
  {"id":"s6p2","type":"paragraph","label":"6.6–6.13","content":"6.6. После погрузки мебели на транспортное средство Заказчика Подрядчик не несёт ответственности за повреждения мебели, произошедшие вследствие нарушения Заказчиком правил транспортировки, выгрузки, условий хранения и эксплуатации.\n6.7. При доставке мебели Подрядчиком Заказчик обязуется подготовить помещение для приёмки, подъезд и проход к нему, создать условия для сохранности мебели при приёмке, обеспечить бесплатную парковку автомобиля Подрядчика на период отгрузки мебели по адресу Заказчика.\n6.8. При уклонении Заказчика от получения мебели, Подрядчик бесплатно хранит мебель в течение 7(семи) дней. С восьмого дня Подрядчик принимает мебель на ответственное хранение, о чём уведомляет Заказчика и вправе взимать плату за хранение в сумме 500 рублей за каждый день. Момент окончания ответственного хранения - передача мебели по акту приёма-передачи. Дополнительных документов о принятии на ответственное хранение, кроме одностороннего уведомления, между сторонами не составляется.\n6.9. При наступлении обстоятельств, объективно препятствующих поставке мебели в согласованные сторонами сроки, Подрядчик вправе в одностороннем порядке изменить срок отгрузки мебели.\n6.10. При получении мебели Заказчик обязан осмотреть её, проверить соответствие качества, количества и комплектности условиям Договора.\n6.11. Риск случайной гибели или повреждения мебели, а также право собственности переходит от Подрядчика к Заказчику в момент подписания соответствующих документов о приёмке.\n6.12. При наличии заказа на услуги монтажа мебели, который оформляется дополнительным договором между Подрядчиком и Заказчиком мебель монтируется Подрядчиком.\n6.13. При отсутствии заказа на монтаж мебели (монтаж (установка) мебели) по настоящему Договору осуществляется Заказчиком самостоятельно и за свой счёт. В этом случае Подрядчик не несёт ответственность за качество монтажных работ и возможные недостатки мебели, возникшие в результате самостоятельного монтажа Заказчиком.","enabled":true,"align":"justify"},
  {"id":"s_claims","type":"paragraph","label":"Претензии","content":"5.2. Мебель, поставляемая в соответствии с настоящим Договором, должна быть осмотрена Заказчиком (уполномоченным представителем Заказчика) на предмет внешних повреждений без нарушения упаковки непосредственно при получении мебели от Подрядчика на складе последнего, либо при доставке по адресу её установки.\n5.3. Приёмка Мебели по количеству и качеству (внешние недостатки) осуществляется:\n5.3.1. При самовывозе: Заказчиком в момент приёмки мебели на складе Подрядчика и подписания акта выполненных работ;\n5.3.2. При доставке: Подрядчиком (грузоперевозчиком Подрядчика): Заказчиком (уполномоченным им грузоперевозчиком или грузополучателем) в момент приёмки мебели от Подрядчика/уполномоченного им грузоперевозчика и подписания акта об оказании услуг.\n5.3.3. Если в будущем сборка мебели будет осуществляться силами ООО «Интерьерные решения» на основании отдельно заключённого договора, то Заказчик обязан вскрыть упаковку в присутствии уполномоченного лица ООО «Интерьерные решения», осуществляющего сборку мебели.\n5.3.4. При обнаружении нарушения целостности упаковки, несоответствия мебели в момент приёмки по качеству и/или количеству, Заказчик делает отметку в акте выполненных работ/оказания услуг. Мебель, в отношении которой у Заказчика имеются замечания, Заказчик принимает на ответственное хранение, о чём делается отметка в акте выполненных работ/оказания услуг. Плата за хранение в этом случае не взимается. Заказчик не вправе использовать (продавать, производить монтаж и т.д.) такую мебель.\n5.4. Претензия по несоответствию мебели количеству, качеству (внешние дефекты), ассортименту направляется Заказчиком в адрес Подрядчика не позднее 3-х рабочих дней с даты поставки мебели с приложением фотографий, фиксирующих факт дефекта мебели либо факт некомплектности, а также фотографию упаковочного ярлыка (бирки), содержащего номер заказа.\n5.4.1. Претензия должна содержать информацию о номере договора, дате приёмки мебели, дате выявления недостатков, наименовании и количестве мебели с недостатками, описание недостатков, местонахождение мебели с недостатками, пожелания Заказчика по урегулированию претензии. К претензии Заказчик обязан приложить фотографии мебели с недостатками, на которых отчётливо различимы все выявленные недостатки. Несоблюдение Заказчиком вышеуказанных требований, является основанием для отклонения претензии Подрядчиком.","enabled":true,"align":"justify"},
  {"id":"s7","type":"section","label":"7. ОТВЕТСТВЕННОСТЬ","content":"7. ОТВЕТСТВЕННОСТЬ СТОРОН","enabled":true,"align":"center"},
  {"id":"s7p","type":"paragraph","label":"7.1–7.5","content":"7.1. Стороны несут ответственность за неисполнение или ненадлежащее исполнение обязательств по Договору в соответствии с Законом Российской Федерации от 7 февраля 1992 г. № 2300-1 «О защите прав потребителей» и иными правовыми актами, принятыми в соответствии с ним.\n7.2. За нарушение сроков оплаты услуг Подрядчик вправе потребовать от Заказчика уплаты неустойки (пени) за каждый день просрочки в размере 0,1 % от суммы задолженности.\n7.3. Подрядчик не несёт ответственности за невыполнение обязательств по Договору, если оно вызвано неисполнением соответствующих обязанностей Заказчика.\n7.4. В случае отказа Заказчика от мебели надлежащего качества, изготовленной по индивидуальному заказу (эскизу), которая имеет нестандартные размеры, цвет, форму, и её дальнейшая реализация невозможна, Стороны признают, что размер убытков Подрядчика составляет стоимость соответствующей (не вывезенной) партии мебели.\n7.5. При разгрузке мебели силами Заказчика материальную ответственность за сохранность груза и автотранспортного средства несёт Заказчик. В случае нанесения ущерба автотранспортному средству Подрядчика (Перевозчика Подрядчика), представителя Заказчика и Подрядчика (или представителя транспортной организации) составляют акт о причинённых повреждениях и причинах возникновения повреждений. При отказе представителя Заказчика от подписи в акте, акт составляется в одностороннем порядке Подрядчиком (представителем транспортной организации) и является основанием для возмещения причинённого ущерба.","enabled":true,"align":"justify"},
  {"id":"s8","type":"section","label":"8. СПОРЫ","content":"8. ПОРЯДОК РАЗРЕШЕНИЯ СПОРОВ","enabled":true,"align":"center"},
  {"id":"s8p","type":"paragraph","label":"8.1–8.3","content":"8.1. Все споры или разногласия, возникающие между Сторонами по настоящему Договору или в связи с ним, разрешаются путём переговоров между ними.\n8.2. До передачи спора на рассмотрение суда Стороны предусматривают обязательный претензионный порядок урегулирования разногласий. Направление претензии возможно по электронной почте, путём обмена сообщениями (Telegram, WhatsApp, СМС и т.д.) на телефонный номер Сторон согласно реквизитам, указанным в Договоре. Срок ответа на претензию Сторон устанавливают в 10 (Десять) рабочих дней с момента получения претензии заинтересованной Стороны.\n8.3. В случае невозможности разрешения разногласий путём переговоров споры или разногласия, возникающие между Сторонами по настоящему Договору или в связи с ним, решаются в судебном порядке по месту нахождения Подрядчика.","enabled":true,"align":"justify"},
  {"id":"s9","type":"section","label":"9. СРОК ДЕЙСТВИЯ","content":"9. СРОК ДЕЙСТВИЯ ДОГОВОРА","enabled":true,"align":"center"},
  {"id":"s9p","type":"paragraph","label":"9.1–9.4","content":"9.1. Договор вступает в силу с момента его подписания обеими Сторонами и действует до полного исполнения Сторонами принятых на себя обязательств.\n9.2. Изменения и дополнения к Договору принимаются по обоюдному соглашению Сторон, путём подписания Дополнительного соглашения к Договору.\n9.3. Договор может быть расторгнут досрочно по письменному соглашению Сторон, в одностороннем порядке в случаях, предусмотренных действующим законодательством Российской Федерации.\n9.4. В случае одностороннего отказа Заказчика от Договора Заказчик обязуется, оплатить Подрядчику фактически понесённые им расходов, связанных с исполнением обязательств по данному Договору.","enabled":true,"align":"justify"},
  {"id":"s10","type":"section","label":"10. ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ","content":"10. ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ","enabled":true,"align":"center"},
  {"id":"s10p","type":"paragraph","label":"10.1–10.3","content":"10.1. При заключении Договора и подписания других документов в рамках его исполнения, Стороны согласны на факсимильное воспроизведение подписи («факсимиле»), уполномоченных лиц, а также на обмен электронными копиями документов. Стороны признают юридически значимой переписку между сторонами по электронной почте, а также переписку по номеру телефона, указанному в настоящем договоре в любых приложениях для обмена сообщениями (Viber, WhatsApp, Telegram, СМС и т.д.). Направленные таким образом документы считаются подписанными простой электронной подписью и признаются Сторонами равнозначными бумажным, подписанным собственноручной подписью Сторон.\n10.2. Стороны признают юридическую силу всех документов, требований, уведомлений, претензий, извещений, оформленных должным образом и направленных друг другу в электронном виде по указанным адресам электронной почты и телефонам во исполнение настоящего Договора. Стороны договорились, что сообщение при такой форме коммуникации считается доставленным тогда, когда приложение, через которое производится коммуникация подтверждает факт направления сообщения через свой внутренний интерфейс. При этом и Заказчик, и Подрядчик обязуются регулярно просматривать указанные источники коммуникации. Стороны договорились, что сообщение считается доставленным и в тех случаях, если оно поступило лицу, которому оно направлено, но по обстоятельствам, зависящим от него, не было ему вручено или адресат не ознакомился с ним.\n10.3. Каждая Сторона обязуется обеспечивать конфиденциальность полученной ею в связи с заключением или исполнением Договора от другой Стороны информации ограниченного доступа.","enabled":true,"align":"justify"},
  {"id":"s10_pd","type":"paragraph","label":"10.4 — Персональные данные","content":"10.4 Заказчик даёт своё согласие на обработку своих персональных данных, а именно: на действия, совершаемые с использованием средств автоматизации или без использования таких средств, включая сбор, запись, систематизацию, накопление, хранение, уточнение (обновление, изменение), извлечение, использование, передачу (распространение, предоставление, доступ), обезличивание, блокирование, удаление, уничтожение его  персональных данных, Обществу с ограниченной ответственностью «ИНТЕРЬЕРНЫЕ РЕШЕНИЯ» (ОГРН: {{огрн}}, ИНН: {{инн}}), расположенному по адресу: 410018, Российская Федерация, Саратовская область, Саратов г., Усть-Курдюмская, 3 помещение 1.\nЦель обработки персональных данных: исполнение настоящего договора. Заказчик даёт своё согласие на использование следующих персональных данных: фамилия, имя, отчество, паспортные данные, адрес места жительства, фотографии изделий на объекте Заказчика; номер телефона, адрес электронной почты. Согласие предоставляется на срок действия настоящего договора, а после прекращения договора - в течение 12 месяцев с даты подписания Сторонами акта сдачи-приёмки выполненных Работ.\nНастоящее условие договора может быть изменено Заказчиком - субъектом персональных данных, в любой момент в одностороннем порядке путём отзыва согласия на обработку персональных данных. Отзыв согласия на обработку персональных данных осуществляется посредством составления письменного документа, который может быть направлен в адрес Подрядчика почтовым отправлением с уведомлением о вручении, либо вручён лично под расписку представителю Подрядчика.","enabled":true,"align":"justify"},
  {"id":"s10_sign","type":"paragraph","label":"Подпись заказчика","content":"_________________________                    /                                                                   /\n             (подпись)                                           (расшифровка подписи от руки)","enabled":true,"align":"left"},
  {"id":"s10_apps","type":"paragraph","label":"10.5 — Приложения","content":"10.5. К настоящему Договору прилагаются и являются неотъемлемой частью следующие приложения:\n1. Технический проект.\n2. Калькуляция работ.\n3. Правила эксплуатации корпусной мебели.\n4. Образец Акта выполненных работ","enabled":true,"align":"justify"},
  {"id":"s11","type":"section","label":"11. РЕКВИЗИТЫ СТОРОН","content":"11. РЕКВИЗИТЫ СТОРОН","enabled":true,"align":"center"},
  {"id":"s11_req","type":"paragraph","label":"Реквизиты","content":"Подрядчик:\n{{компания}}\nИНН/КПП: {{инн_кпп}}\nОГРН: {{огрн}}\nЮридический и фактический адрес: {{адрес_компании}}\nБанковские реквизиты:\n{{банк}}\nБИК: {{бик}}\nРас/с: {{расчётный_счёт}}\nКорп/с: {{корр_счёт}}\nТелефон: {{телефон_компании}}\nE-mail: {{email_компании}}\n\nМенеджер:\n{{менеджер}}\n\n_________________________          _________________________\n                                                    М.П.","enabled":true,"align":"left"},
  {"id":"s11_client","type":"paragraph","label":"Реквизиты заказчика","content":"Заказчик:\n{{имя_клиента}}\nПаспорт. Серия, номер:\n{{паспорт}}\nКем выдан:\n{{паспорт_выдан}}\n\nАдрес прописки:\n{{адрес_регистрации}}\n\nТелефон:\n{{телефон_клиента}}\nПредпочитаемый канал обмена сообщениями:\n{{мессенджер}}\n\n\n_________________________","enabled":true,"align":"left"}
]'::jsonb, updated_at = now()
WHERE doc_type = 'contract' AND is_default = true;
